  apply (nested_overflow_lift tm Cc Cin lapin_0RB0LD_0LC1LD_1LD1RC_0RC1LA p (pow2 j)).
  - exists (4 * j + 9), (cden [] [] j BB1_0RB0LD_0LC1LD_1LD1RC_0RC1LA).
    split; [lia|]. split; [| exact (gbo_0RB0LD_0LC1LD_1LD1RC_0RC1LA j)].
    rewrite (gso_0RB0LD_0LC1LD_1LD1RC_0RC1LA p j E).
    exact (srun_sound tm true true chb_0RB0LD_0LC1LD_1LD1RC_0RC1LA B0_0RB0LD_0LC1LD_1LD1RC_0RC1LA BB1_0RB0LD_0LC1LD_1LD1RC_0RC1LA 4 9
             run_boot_0RB0LD_0LC1LD_1LD1RC_0RC1LA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (4 * j + 9), (cden [] [] j B1_0RB0LD_0LC1LD_1LD1RC_0RC1LA).
    split; [| exact (geo_0RB0LD_0LC1LD_1LD1RC_0RC1LA p j E)].
