  - exact bootq_0RB0LD_0LC1LD_1LD1RC_0RC1LA.
  - intros p _. apply lap_0RB0LD_0LC1LD_1LD1RC_0RC1LA.
  - intros t Ht p _. apply fire_0RB0LD_0LC1LD_1LD1RC_0RC1LA. exact Ht.
  - exact wit_0RB0LD_0LC1LD_1LD1RC_0RC1LA.
  - apply qcleb_QC_04. reflexivity.
Qed.

Theorem qhtr_0RB0LD_0LC1LD_1LD1RC_0RC1LA : NonHalt tm_0RB0LD_0LC1LD_1LD1RC_0RC1LA /\ QHBoundTr 32779478 tm_0RB0LD_0LC1LD_1LD1RC_0RC1LA /\ QuasiHaltsTr tm_0RB0LD_0LC1LD_1LD1RC_0RC1LA.
