  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_0RB0LD_0LC1RC_1LD1RC_0RC1LA
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_0RB0LD_0LC1RC_1LD1RC_0RC1LA
      with (l := [SRotL 1; SWin 1; SRotL 1; SWin 1; SCycL 2 0; SWin 1]).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_0RB0LD_0LC1RC_1LD1RC_0RC1LA
      with (l := [SRotL 1; SWin 1; SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_0RB0LD_0LC1RC_1LD1RC_0RC1LA
      with (l := [SRotL 1; SWin 1; SRotL 1; SWin 1; SCycL 2 0; SWin 2; SCycR 2; SWin 2]).
    vm_compute; reflexivity.
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_0RB0LD_0LC1RC_1LD1RC_0RC1LA
      with (l := [SRotL 1; SWin 1; SRotL 1; SWin 1; SCycL 2 0; SWin 2]).
    vm_compute; reflexivity.
Qed.

Theorem qhtrm_0RB0LD_0LC1RC_1LD1RC_0RC1LA : NonHalt tmm_0RB0LD_0LC1RC_1LD1RC_0RC1LA /\ QHBoundTr 32779478 tmm_0RB0LD_0LC1RC_1LD1RC_0RC1LA /\ QuasiHaltsTr tmm_0RB0LD_0LC1RC_1LD1RC_0RC1LA.
