  - intros t Ht p _. apply fire_0RB0LD_0LC1RC_1LD1RC_0RC1LA. exact Ht.
  - exact wit_0RB0LD_0LC1RC_1LD1RC_0RC1LA.
  - apply qcleb_QC_04. reflexivity.
