Theorem qhtr_0RB0LD_0LC1RC_1LD1RC_0RC1LA : NonHalt tm_0RB0LD_0LC1RC_1LD1RC_0RC1LA /\ QHBoundTr 32779478 tm_0RB0LD_0LC1RC_1LD1RC_0RC1LA /\ QuasiHaltsTr tm_0RB0LD_0LC1RC_1LD1RC_0RC1LA.
