      with (l := [SRotL 1; SWin 5]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_0RB0LD_0RC0LD_1LD1RC_0RC1LA
      with (l := [SRotL 1; SWin 2]).
    vm_compute; reflexivity.
  - (* D1 *)
