    apply (fire_via_ovf_lift tm Cc Hi (StC, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB0LD_1RC0LD_1LA1RB_0RB1LD [SCycL 2 0; SWin 4; SWinL 1] (StC, S0) ltac:(vm_compute; reflexivity)
