  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_0RB0LD_1RC1LD_1LD1RC_0RC1LA
      with (l := [SRotL 1; SWin 3; SCycL 2 0; SWin 4]).
    vm_compute; reflexivity.
  - (* B0: pinned *)
