    split; [lia|]. split; [| exact HB].
    rewrite HA.
    exact (srun_sound tm false true chz_0RB0LD_1RC____1LA1RB_0RB0LD Z0_0RB0LD_1RC____1LA1RB_0RB0LD Z1_0RB0LD_1RC____1LA1RB_0RB0LD 0 4
             run_z_0RB0LD_1RC____1LA1RB_0RB0LD (Ap_Alph_00_10_1 q0 ++ [S0]) [] 0
             ltac:(discriminate) ltac:(reflexivity)).
  - destruct (gp_0RB0LD_1RC____1LA1RB_0RB0LD p j' q0 E) as (HA & HB).
    exists (4 * j' + 8), (cden (Ap_Alph_00_10_1 q0 ++ [S0]) [] j' P1_0RB0LD_1RC____1LA1RB_0RB0LD).
    split; [lia|]. split; [| exact HB].
    rewrite HA.
