Lemma geo_0RB0LD_1RC____1LA1RB_0RB0LD : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_0RB0LD_1RC____1LA1RB_0RB0LD) = lift (Cc (Pos.succ p)).
