(** ** The lap *)

Lemma lap_0RB0LD_1RC____1LA1RB_0RB0LD : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_0RB0LD_1RC____1LA1RB_0RB0LD p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_0RB0LD_1RC____1LA1RB_0RB0LD B0_0RB0LD_1RC____1LA1RB_0RB0LD B1_0RB0LD_1RC____1LA1RB_0RB0LD 4 8 p j' [] []).
    + exact run_ovf_0RB0LD_1RC____1LA1RB_0RB0LD.
    + reflexivity.
    + reflexivity.
    + exact (gso_0RB0LD_1RC____1LA1RB_0RB0LD p j' E).
    + exact (geo_0RB0LD_1RC____1LA1RB_0RB0LD p j' E).
    + lia.
