(** the quasihalt witness: a pinned instruction fired in the prefix *)
Lemma wit_0RB0LD_1RC____1LA1RB_0RB0LD : existsb (fun tg => cfires tmm_0RB0LD_1RC____1LA1RB_0RB0LD c0 5 tg) pins_0RB0LD_1RC____1LA1RB_0RB0LD = true.
