  - intros t Ht p _. apply fire_0RB0LD_1RC____1LA1RB_0RB0LD. exact Ht.
  - exact wit_0RB0LD_1RC____1LA1RB_0RB0LD.
  - apply qcleb_QC_04. reflexivity.
