  exists (4 * j + 8), (cden (Jp q0 ++ [S0;S1;S0]) [] j A1_0RB0RB_0LC1RB_1LD0RB_1RA1LC).
  split; [lia|]. split; [| exact (gei_0RB0RB_0LC1RB_1LD0RB_1RA1LC p j q0 E)].
  rewrite (gsi_0RB0RB_0LC1RB_1LD0RB_1RA1LC p j q0 E).
  exact (srun_sound tm false true chi_0RB0RB_0LC1RB_1LD0RB_1RA1LC A0_0RB0RB_0LC1RB_1LD0RB_1RA1LC A1_0RB0RB_0LC1RB_1LD0RB_1RA1LC 4 8
           run_int_0RB0RB_0LC1RB_1LD0RB_1RA1LC (Jp q0 ++ [S0;S1;S0]) [] j
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

Lemma gso_0RB0RB_0LC1RB_1LD0RB_1RA1LC : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_0RB0RB_0LC1RB_1LD0RB_1RA1LC.
Proof.
