  unfold Cc_0RB0RB_0LC1RB_1LD0RB_1RA1LC, cden, B0_0RB0RB_0LC1RB_1LD0RB_1RA1LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_0RB0RB_0LC1RB_1LD0RB_1RA1LC : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_0RB0RB_0LC1RB_1LD0RB_1RA1LC : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_0RB0RB_0LC1RB_1LD0RB_1RA1LC) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (JpCounter.cview_none_J p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_0RB0RB_0LC1RB_1LD0RB_1RA1LC
             = (StC, (rep [S1;S1] (S j) ++ [S1;S0;S1], S0, ([]) ++ [S0]))).
  { unfold cden, B1_0RB0RB_0LC1RB_1LD0RB_1RA1LC, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StC, ((rep [S1;S1] (S j) ++ [S1;S0;S1]) ++ [S0], S0, []))).
  { unfold Cc_0RB0RB_0LC1RB_1LD0RB_1RA1LC. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lift_app_blank. rewrite !lbl_0RB0RB_0LC1RB_1LD0RB_1RA1LC. reflexivity.
