(** ** The lap *)

Lemma lap_0RB0RB_0LC1RB_1LD0RB_1RA1LC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
