  - destruct (lapi_0RB0RB_0LC1RB_1LD0RB_1RA1LC p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
