    apply (lap_of_run tm Cc true true cho_0RB0RB_0LC1RB_1LD0RB_1RA1LC B0_0RB0RB_0LC1RB_1LD0RB_1RA1LC B1_0RB0RB_0LC1RB_1LD0RB_1RA1LC 4 14 p j' [] []).
    + exact run_ovf_0RB0RB_0LC1RB_1LD0RB_1RA1LC.
    + reflexivity.
    + reflexivity.
    + exact (gso_0RB0RB_0LC1RB_1LD0RB_1RA1LC p j' E).
    + exact (geo_0RB0RB_0LC1RB_1LD0RB_1RA1LC p j' E).
    + lia.
