(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_0RB0RC_1LC1LC_0LD1RA_1RC1LD : list Instr := [(StB, S0)].
Definition tmw_0RB0RC_1LC1LC_0LD1RA_1RC1LD : TM := tm_wrap_trs tm_0RB0RC_1LC1LC_0LD1RA_1RC1LD pins_0RB0RC_1LC1LC_0LD1RA_1RC1LD.
Local Notation tm := tmw_0RB0RC_1LC1LC_0LD1RA_1RC1LD.

Definition Cc_0RB0RC_1LC1LC_0LD1RA_1RC1LD (p : positive) : cconf := (StA, (Ap_Alph_10_11_11 p ++ [S0], S0, [S1])).
Local Notation Cc := Cc_0RB0RC_1LC1LC_0LD1RA_1RC1LD.

(** ** The certificate *)

Definition A0_0RB0RC_1LC1LC_0LD1RA_1RC1LD : sconf := mkC StA (mkS [] [S1;S1] 1 0 [S1;S0]) S0 (mkS [S1] [] 0 0 []).
Definition A1_0RB0RC_1LC1LC_0LD1RA_1RC1LD : sconf := mkC StA (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [S1] [] 0 0 []).
Definition chi_0RB0RC_1LC1LC_0LD1RA_1RC1LD : list lstep := [SWin 2; SRotL 1; SWin 1; SCycL 2 0; SWin 2; SCycR 2; SWin 1; SUnrotL 1].

Lemma run_int_0RB0RC_1LC1LC_0LD1RA_1RC1LD : srun tm false true chi_0RB0RC_1LC1LC_0LD1RA_1RC1LD A0_0RB0RC_1LC1LC_0LD1RA_1RC1LD = Some (A1_0RB0RC_1LC1LC_0LD1RA_1RC1LD, 4, 6).
Proof. vm_compute. reflexivity. Qed.

Definition B0_0RB0RC_1LC1LC_0LD1RA_1RC1LD : sconf := mkC StA (mkS [] [S1;S1] 1 0 [S1;S1;S0]) S0 (mkS [S1] [] 0 0 []).
Definition B1_0RB0RC_1LC1LC_0LD1RA_1RC1LD : sconf := mkC StA (mkS [] [S1;S0] 1 1 [S1;S1]) S0 (mkS [S1] [] 0 0 []).
(** ** The INNER anchor family -- Ip at StD *)
Definition Cin_0RB0RC_1LC1LC_0LD1RA_1RC1LD (v : positive) : cconf := (StD, (Ip v ++ [S1], S0, [S0;S1])).
Local Notation Cin := Cin_0RB0RC_1LC1LC_0LD1RA_1RC1LD.

(** [E (2^n) = A^n C]: the value this family's count starts at. *)
Lemma epow2_0RB0RC_1LC1LC_0LD1RA_1RC1LD : forall n, Ip (pow2 n) = rep [S1;S0] n ++ [S1].
Proof. induction n; simpl; [reflexivity | rewrite IHn; reflexivity]. Qed.

(** Its own INTERIOR lap -- ordinary and affine.  Iterating it to the fill is
    where a [Theta(2^j)] lives, and [inner_to_fill_lift] keeps it inside an
    existential. *)
Definition AI0_0RB0RC_1LC1LC_0LD1RA_1RC1LD : sconf := mkC StD (mkS [] [S1;S1] 1 0 [S1;S0]) S0 (mkS [S0;S1] [] 0 0 []).
Definition AI1_0RB0RC_1LC1LC_0LD1RA_1RC1LD : sconf := mkC StD (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [S0;S1] [] 0 0 []).
Definition chn_0RB0RC_1LC1LC_0LD1RA_1RC1LD : list lstep := [SWin 2; SCycL 2 0; SWin 4; SCycR 2; SWin 2].

Lemma run_inner_0RB0RC_1LC1LC_0LD1RA_1RC1LD : srun tm false true chn_0RB0RC_1LC1LC_0LD1RA_1RC1LD AI0_0RB0RC_1LC1LC_0LD1RA_1RC1LD = Some (AI1_0RB0RC_1LC1LC_0LD1RA_1RC1LD, 4, 8).
Proof. vm_compute. reflexivity. Qed.

(** *** boot: the outer overflow anchor -> the first inner anchor at [pow2 j] *)
Definition BB1_0RB0RC_1LC1LC_0LD1RA_1RC1LD : sconf := mkC StD (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [S0;S1] [] 0 0 []).
Definition chb_0RB0RC_1LC1LC_0LD1RA_1RC1LD : list lstep := [SWin 2; SRotL 1; SWin 1; SCycL 2 0; SWin 4; SCycR 2; SWin 2].

Lemma run_boot_0RB0RC_1LC1LC_0LD1RA_1RC1LD : srun tm true true chb_0RB0RC_1LC1LC_0LD1RA_1RC1LD B0_0RB0RC_1LC1LC_0LD1RA_1RC1LD = Some (BB1_0RB0RC_1LC1LC_0LD1RA_1RC1LD, 4, 9).
Proof. vm_compute. reflexivity. Qed.

(** *** exit: the last inner all-ones fill -> the outer successor *)
Definition BE0_0RB0RC_1LC1LC_0LD1RA_1RC1LD : sconf := mkC StD (mkS [] [S1;S1] 1 0 [S1;S1]) S0 (mkS [S0;S1] [] 0 0 []).
Definition che_0RB0RC_1LC1LC_0LD1RA_1RC1LD : list lstep := [SWin 2; SCycL 2 0; SWin 2; SWinL 4; SCycR 2; SWin 1; SRotL 1; SFoldL 1].

Lemma run_exit_0RB0RC_1LC1LC_0LD1RA_1RC1LD : srun tm true true che_0RB0RC_1LC1LC_0LD1RA_1RC1LD BE0_0RB0RC_1LC1LC_0LD1RA_1RC1LD = Some (B1_0RB0RC_1LC1LC_0LD1RA_1RC1LD, 4, 9).
Proof. vm_compute. reflexivity. Qed.

(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_0RB0RC_1LC1LC_0LD1RA_1RC1LD : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j A0_0RB0RC_1LC1LC_0LD1RA_1RC1LD.
Proof.
  intros p j q0 E. destruct (Alph_10_11_11.cview_some_Alph_10_11_11 p j q0 E) as (H1 & _).
  unfold Cc_0RB0RC_1LC1LC_0LD1RA_1RC1LD, cden, A0_0RB0RC_1LC1LC_0LD1RA_1RC1LD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S1] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gei_0RB0RC_1LC1LC_0LD1RA_1RC1LD : forall p j q0, cview p = (j, Some q0) ->
  cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j A1_0RB0RC_1LC1LC_0LD1RA_1RC1LD = Cc (Pos.succ p).
Proof.
  intros p j q0 E. destruct (Alph_10_11_11.cview_some_Alph_10_11_11 p j q0 E) as (_ & H2).
  unfold Cc_0RB0RC_1LC1LC_0LD1RA_1RC1LD, cden, A1_0RB0RC_1LC1LC_0LD1RA_1RC1LD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S0] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_0RB0RC_1LC1LC_0LD1RA_1RC1LD : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. exists (4 * j + 6). split; [lia|].
  rewrite (gsi_0RB0RC_1LC1LC_0LD1RA_1RC1LD p j q0 E).
  rewrite (srun_sound tm false true chi_0RB0RC_1LC1LC_0LD1RA_1RC1LD A0_0RB0RC_1LC1LC_0LD1RA_1RC1LD A1_0RB0RC_1LC1LC_0LD1RA_1RC1LD 4 6
             run_int_0RB0RC_1LC1LC_0LD1RA_1RC1LD (Ap_Alph_10_11_11 q0 ++ [S0]) [] j
             ltac:(discriminate) ltac:(reflexivity)).
  f_equal. exact (gei_0RB0RC_1LC1LC_0LD1RA_1RC1LD p j q0 E).
Qed.

Lemma gso_0RB0RC_1LC1LC_0LD1RA_1RC1LD : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_0RB0RC_1LC1LC_0LD1RA_1RC1LD.
Proof.
  intros p j E. destruct (Alph_10_11_11.cview_none_Alph_10_11_11 p j E) as (H1 & _).
  unfold Cc_0RB0RC_1LC1LC_0LD1RA_1RC1LD, cden, B0_0RB0RC_1LC1LC_0LD1RA_1RC1LD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_0RB0RC_1LC1LC_0LD1RA_1RC1LD : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_0RB0RC_1LC1LC_0LD1RA_1RC1LD : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_0RB0RC_1LC1LC_0LD1RA_1RC1LD) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (Alph_10_11_11.cview_none_Alph_10_11_11 p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_0RB0RC_1LC1LC_0LD1RA_1RC1LD
             = (StA, (rep [S1;S0] (S j) ++ [S1;S1], S0, [S1]))).
  { unfold cden, B1_0RB0RC_1LC1LC_0LD1RA_1RC1LD, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StA, ((rep [S1;S0] (S j) ++ [S1;S1]) ++ [S0], S0, [S1]))).
  { unfold Cc_0RB0RC_1LC1LC_0LD1RA_1RC1LD. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lbl_0RB0RC_1LC1LC_0LD1RA_1RC1LD. reflexivity.
Qed.

Lemma gsn_0RB0RC_1LC1LC_0LD1RA_1RC1LD : forall v i q0, cview v = (i, Some q0) ->
  Cin v = cden (Ip q0 ++ [S1]) [] i AI0_0RB0RC_1LC1LC_0LD1RA_1RC1LD.
Proof.
  intros v i q0 E. destruct (ILCounter.cview_some_I v i q0 E) as (H1 & _).
  unfold Cin_0RB0RC_1LC1LC_0LD1RA_1RC1LD, cden, AI0_0RB0RC_1LC1LC_0LD1RA_1RC1LD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S1] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gen_0RB0RC_1LC1LC_0LD1RA_1RC1LD : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Ip q0 ++ [S1]) [] i AI1_0RB0RC_1LC1LC_0LD1RA_1RC1LD) = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E. destruct (ILCounter.cview_some_I v i q0 E) as (_ & H2).
  unfold Cin_0RB0RC_1LC1LC_0LD1RA_1RC1LD, cden, AI1_0RB0RC_1LC1LC_0LD1RA_1RC1LD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  replace (0 * i + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S0] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapin_0RB0RC_1LC1LC_0LD1RA_1RC1LD : forall v i q0, cview v = (i, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cin v) = Some c'
               /\ lift c' = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E.
  exists (4 * i + 8), (cden (Ip q0 ++ [S1]) [] i AI1_0RB0RC_1LC1LC_0LD1RA_1RC1LD).
  split; [lia|]. split; [| exact (gen_0RB0RC_1LC1LC_0LD1RA_1RC1LD v i q0 E)].
  rewrite (gsn_0RB0RC_1LC1LC_0LD1RA_1RC1LD v i q0 E).
  exact (srun_sound tm false true chn_0RB0RC_1LC1LC_0LD1RA_1RC1LD AI0_0RB0RC_1LC1LC_0LD1RA_1RC1LD AI1_0RB0RC_1LC1LC_0LD1RA_1RC1LD 4 8
           run_inner_0RB0RC_1LC1LC_0LD1RA_1RC1LD (Ip q0 ++ [S1]) [] i
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

(** The chain into this family lands on its anchor up to 0/0
    trailing blanks. *)
Lemma gbo_0RB0RC_1LC1LC_0LD1RA_1RC1LD : forall j, lift (cden [] [] j BB1_0RB0RC_1LC1LC_0LD1RA_1RC1LD) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_0RB0RC_1LC1LC_0LD1RA_1RC1LD = (StD, (rep [S1;S0] j ++ [S1;S1], S0, [S0;S1]))).
  { unfold cden, BB1_0RB0RC_1LC1LC_0LD1RA_1RC1LD, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (pow2 j) = (StD, (rep [S1;S0] j ++ [S1;S1], S0, [S0;S1]))).
  { unfold Cin_0RB0RC_1LC1LC_0LD1RA_1RC1LD. rewrite epow2_0RB0RC_1LC1LC_0LD1RA_1RC1LD.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite ?lbl_0RB0RC_1LC1LC_0LD1RA_1RC1LD. rewrite ?lift_app_blank. reflexivity.
Qed.

(** This family's all-ones fill IS the next chain's start.  [cview (fill
    (pow2 j)) = (S j, None)] ([NestedLapLift.cview_fill_pow2]), so the
    family's own overflow decomposition names the word. *)
Lemma gxi_0RB0RC_1LC1LC_0LD1RA_1RC1LD : forall j, Cin (fill (pow2 j)) = cden [] [] j BE0_0RB0RC_1LC1LC_0LD1RA_1RC1LD.
Proof.
  intro j.
  destruct (ILCounter.cview_none_I (fill (pow2 j)) j (cview_fill_pow2 j)) as (H1 & _).
  unfold Cin_0RB0RC_1LC1LC_0LD1RA_1RC1LD, cden, BE0_0RB0RC_1LC1LC_0LD1RA_1RC1LD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- ?app_assoc; cbn [app];
        rewrite ?app_nil_r; reflexivity | reflexivity ].
Qed.

(** The interior lap, restated up to [lift] -- what [vis_via_ovf_lift] and
    [vis_via_fill] consume. *)
Lemma lapil_0RB0RC_1LC1LC_0LD1RA_1RC1LD : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof. intros p j q0 E. destruct (lapi_0RB0RC_1LC1LC_0LD1RA_1RC1LD p j q0 E) as (n & Hn & Hr).
  exists n, (Cc (Pos.succ p)).
  split; [exact Hn | split; [exact Hr | reflexivity]]. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_0RB0RC_1LC1LC_0LD1RA_1RC1LD : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_0RB0RC_1LC1LC_0LD1RA_1RC1LD p (pow2 j)).
  - exists (4 * j + 9), (cden [] [] j BB1_0RB0RC_1LC1LC_0LD1RA_1RC1LD).
    split; [lia|]. split; [| exact (gbo_0RB0RC_1LC1LC_0LD1RA_1RC1LD j)].
    rewrite (gso_0RB0RC_1LC1LC_0LD1RA_1RC1LD p j E).
    exact (srun_sound tm true true chb_0RB0RC_1LC1LC_0LD1RA_1RC1LD B0_0RB0RC_1LC1LC_0LD1RA_1RC1LD BB1_0RB0RC_1LC1LC_0LD1RA_1RC1LD 4 9
             run_boot_0RB0RC_1LC1LC_0LD1RA_1RC1LD [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (4 * j + 9), (cden [] [] j B1_0RB0RC_1LC1LC_0LD1RA_1RC1LD).
    split; [| exact (geo_0RB0RC_1LC1LC_0LD1RA_1RC1LD p j E)].
    rewrite (gxi_0RB0RC_1LC1LC_0LD1RA_1RC1LD j).
    exact (srun_sound tm true true che_0RB0RC_1LC1LC_0LD1RA_1RC1LD BE0_0RB0RC_1LC1LC_0LD1RA_1RC1LD B1_0RB0RC_1LC1LC_0LD1RA_1RC1LD 4 9
             run_exit_0RB0RC_1LC1LC_0LD1RA_1RC1LD [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_0RB0RC_1LC1LC_0LD1RA_1RC1LD : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_0RB0RC_1LC1LC_0LD1RA_1RC1LD p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_0RB0RC_1LC1LC_0LD1RA_1RC1LD p j' E).
Qed.

(** ** Bootstrap *)

Lemma bootq_0RB0RC_1LC1LC_0LD1RA_1RC1LD : stepn tm_0RB0RC_1LC1LC_0LD1RA_1RC1LD 8 InitES = Some (lift (Cc 1)).
Proof.
  assert (H : match csteps tm_0RB0RC_1LC1LC_0LD1RA_1RC1LD 8 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm_0RB0RC_1LC1LC_0LD1RA_1RC1LD 8 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** the quasihalt witness: a pinned instruction fired in the prefix *)
Lemma wit_0RB0RC_1LC1LC_0LD1RA_1RC1LD : existsb (fun tg => cfires tm_0RB0RC_1LC1LC_0LD1RA_1RC1LD c0 8 tg) pins_0RB0RC_1LC1LC_0LD1RA_1RC1LD = true.
Proof. vm_compute. reflexivity. Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_0RB0RC_1LC1LC_0LD1RA_1RC1LD : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_0RB0RC_1LC1LC_0LD1RA_1RC1LD = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_0RB0RC_1LC1LC_0LD1RA_1RC1LD p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_0RB0RC_1LC1LC_0LD1RA_1RC1LD p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_0RB0RC_1LC1LC_0LD1RA_1RC1LD : forall t, ~ In t pins_0RB0RC_1LC1LC_0LD1RA_1RC1LD ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_0RB0RC_1LC1LC_0LD1RA_1RC1LD.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_via_ovf tm Cc Hi (StA, S0)), fireo_0RB0RC_1LC1LC_0LD1RA_1RC1LD
      with (l := []).
    vm_compute; reflexivity.
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_0RB0RC_1LC1LC_0LD1RA_1RC1LD
      with (l := [SWin 2; SRotL 1; SWin 1; SCycL 2 0; SWin 4]).
    vm_compute; reflexivity.
  - (* B0: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_0RB0RC_1LC1LC_0LD1RA_1RC1LD
      with (l := [SWin 1]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_0RB0RC_1LC1LC_0LD1RA_1RC1LD
      with (l := [SWin 2]).
